// Lucide icons (ISC; some derived from Feather, MIT; full notices in
// docs/THIRD_PARTY_NOTICES.md). The shapes come from icon-data.js, generated by
// scripts/icons.mjs; this draws the shared 24x24 outline <svg> around them.
// Icons take the current text color, so they follow the theme, and their size
// from CSS (.icon is 1em by default). Always decorative: the button or link
// around an icon carries the name (visible text or aria-label).
import { ICON_DATA } from './icon-data.js';

const SVG = 'http://www.w3.org/2000/svg';

/**
 * The attributes and shapes for one icon, without touching the DOM.
 * @param {string} name A Lucide name listed in scripts/icons.mjs.
 * @param {{filled?: boolean, className?: string}} [options] `filled` fills the shape (a favorite's star).
 */
export function iconSpec(name, { filled = false, className = '' } = {}) {
  const children = ICON_DATA[name];
  if (!children) throw new Error(`Unknown icon "${name}". Add it to scripts/icons.mjs and run npm run icons.`);
  return {
    attrs: {
      viewBox: '0 0 24 24', fill: filled ? 'currentColor' : 'none', stroke: 'currentColor', 'stroke-width': '2',
      'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'aria-hidden': 'true', focusable: 'false',
      class: `icon icon-${name}${className ? ` ${className}` : ''}`,
    },
    children,
  };
}

/**
 * An icon as an <svg> element.
 * @param {string} name
 * @param {{filled?: boolean, className?: string}} [options]
 * @returns {SVGSVGElement}
 */
export function icon(name, options) {
  const { attrs, children } = iconSpec(name, options);
  const svg = /** @type {SVGSVGElement} */ (document.createElementNS(SVG, 'svg'));
  for (const [key, value] of Object.entries(attrs)) svg.setAttribute(key, value);
  for (const [tag, shapeAttrs] of children) {
    const shape = document.createElementNS(SVG, tag);
    for (const [key, value] of Object.entries(shapeAttrs)) shape.setAttribute(key, value);
    svg.append(shape);
  }
  return svg;
}
